style.css:
/* Background in light pink */
body {
  background-color: #FFC0CB; /* Light Pink */
  font-family: Arial, sans-serif;
  color: #333; /* Dark text for contrast */
}

/* Hot pink button */
button {
  background-color: #FF69B4; /* Hot Pink */
  color: white;
  border: none;
  padding: 10px 20px;
  border-radius: 5px;
  cursor: pointer;
  font-size: 16px;
}

/* Hover effect for the button */
button:hover {
  background-color: #FF1493; /* Deep Pink */
}

/* Rose pink heading */
h1 {
  color: #FF007F; /* Rose Pink */
  text-align: center;
}

/* Coral pink paragraph */
p {
  color: #F88379; /* Coral Pink */
  font-size: 18px;
  line-height: 1.6;
}
